<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \`path/to/file.ts\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`functionName()\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — [what is wrong here]</span></span>
